"""Summarize node sequence gaps without changing the node."""
import json
from pathlib import Path
import re
import stat
import sys


def reject_constant(value):
    raise ValueError(value)


def read_json(raw):
    return json.loads(raw.decode("utf-8"), parse_constant=reject_constant)


def regular_logs(folder, channel):
    numbered = re.compile(rf"{channel}\.[0-9]{{12}}\.jsonl\Z")
    paths = []
    for path in folder.iterdir():
        if (numbered.fullmatch(path.name) or path.name == f"{channel}.active.jsonl") and stat.S_ISREG(path.stat(follow_symlinks=False).st_mode):
            paths.append(path)
    return sorted(paths, key=lambda path: (path.name == f"{channel}.active.jsonl", path.name))


def read_logs(folder, channel, bad):
    counts = {}
    for path in regular_logs(folder, channel):
        parts = path.read_bytes().split(b"\n")
        for line, raw in enumerate(parts, 1):
            if line == len(parts):
                if raw:
                    bad.append({"file": path.name, "line": line, "why": "torn"})
                break
            try:
                record = read_json(raw)
            except (UnicodeError, ValueError):
                bad.append({"file": path.name, "line": line, "why": "bad_json"})
                continue
            seq = record.get("seq") if isinstance(record, dict) else None
            if type(seq) is not int or seq < 1:
                bad.append({"file": path.name, "line": line, "why": "no_seq"})
                continue
            counts[seq] = counts.get(seq, 0) + 1
    return counts


def read_state(folder):
    try:
        raw = (folder / "state.json").read_bytes()
    except FileNotFoundError:
        return None, False
    except OSError:
        return None, True
    try:
        value = read_json(raw)
    except (UnicodeError, ValueError):
        return None, True
    if not isinstance(value, dict) or not isinstance(value.get("channels"), dict):
        return None, True
    return value["channels"], False


def summarize(folder):
    bad = []
    state, state_bad = read_state(folder)
    channels = {}
    for channel in ("obs", "must"):
        counts = read_logs(folder, channel, bad)
        seqs = sorted(counts)
        last = seqs[-1] if seqs else None
        result = {
            "count": sum(counts.values()),
            "first": seqs[0] if seqs else None,
            "last": last,
            "missing": [[a + 1, b - 1] for a, b in zip(seqs, seqs[1:]) if b > a + 1],
            "dup": [seq for seq in seqs if counts[seq] >= 2],
            "next_seq": None,
            "unacked": None,
            "stale_next": None,
        }
        if state is not None:
            fields = state.get(channel)
            valid = isinstance(fields, dict) and type(fields.get("next_seq")) is int
            if channel == "must":
                valid = valid and type(fields.get("acked_upto")) is int
            if valid:
                result["next_seq"] = fields["next_seq"]
                result["stale_next"] = None if last is None else fields["next_seq"] != last + 1
                if channel == "must":
                    result["unacked"] = sum(seq > fields["acked_upto"] for seq in seqs)
            else:
                state_bad = True
        channels[channel] = result
    if state_bad:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    bad.sort(key=lambda item: (item["file"], 0 if item["line"] is None else item["line"], item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        print("usage: aos7-evgap <folder>", file=sys.stderr)
        return 2
    print(json.dumps(summarize(Path(args[0])), separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
